/**
 * What the Worker receives in `env`.
 *
 * `Cloudflare.Env` is generated by `wrangler types` from wrangler.jsonc. The secrets aren't in that
 * file, so they are added here. They are optional on purpose: the Worker is deployed before the
 * secrets are set with `wrangler secret put`, and until then they are undefined.
 */
export type Env = Cloudflare.Env & {
	/** The 48-hex-character token in the MCP URL: /<MCP_TOKEN>/mcp. */
	MCP_TOKEN?: string;
	/** A fine-grained GitHub token for NOTES_REPO only, with Contents access. */
	GITHUB_TOKEN?: string;
};
